import {checkGpuEnvironment} from './gpu-environment.js';
import {exteriorFluidSource} from './fluid-domain.js';
import {STEFAN_BOLTZMANN} from './thermal-radiation.js';
import {createViewApi,visiblePoint,firstVisibleHit} from './view-settings.js';
import {prepareCaseView} from './case-view.js';
import {createCaseStore} from './cases.js';
import {sampleResult} from './probe.js';
import {frameFromEuler} from './constraints.js';
import {selectedRefinements} from './local-mesh.js';
import {createAnalysisClient} from './analysis-client.js';
import {installLanguage,language} from './i18n.js';
import { materialFields,materialReadiness } from './materials.js';
import { createStudioApi } from './studio-api.js';
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { STLLoader } from 'three/addons/loaders/STLLoader.js';
import { areaOfTriangle, brushTriangles, validateProject } from './regions.js';
import './style.css';

document.querySelector('#app').innerHTML=`
<header><div><h1>Airpocket <span style="color:#77dbd1">Simulation Studio</span></h1><small>3D上で、解析する場所を決める</small></div><span class="badge">構造・熱・流体・音響 · v0.23</span><a class="dev-link" href="./development.html">開発管理 ↗</a></header>
<div class="layout"><aside><section><h2>01 モデル</h2><label class="file">STEP / STL を開く<input id="model" type="file" accept=".step,.stp,.stl"></label><div class="row"><button id="demo">曲面サンプル</button><button id="analysis-demo">解析サンプル</button><button id="pressure-demo">圧力・重力サンプル</button><button id="displacement-demo">指定変位サンプル</button><button id="rubber-demo">ゴム大変形サンプル</button><button id="thermal-stress-demo">熱応力サンプル</button><button id="thermal-demo">熱サンプル</button><button id="exterior-demo">外部流体領域サンプル</button><button id="flow-demo">層流流路サンプル</button><button id="contact-demo">接触熱抵抗サンプル</button><button id="radiation-demo">熱放射サンプル</button><button id="convection-demo">放熱サンプル</button><button id="acoustic-demo">音響サンプル</button><button id="impedance-demo">吸音境界サンプル</button><button id="cavity-demo">空洞サンプル</button><button id="fit">全体表示</button></div><label>STLの長さ単位<select id="unit"><option value="1">mm</option><option value="10">cm</option><option value="1000">m</option></select></label><p>STEPはmmに変換。ファイルはこのブラウザで処理します。</p></section>
<section><h2>外部流体領域</h2><label>部品から囲いまでの余白（mm）<input id="fluid-padding" type="number" value="10" min="0.001" max="10000" step="any"></label><button id="exterior-create">周囲の流体領域を作る</button><p>囲いの箱から元の部品体積を差し引いてメッシュを作ります。閉じた内部空洞は外部領域から除外します。一般3D流体のソルバーと内部流路の自動抽出は未対応です。</p><p id="fluid-domain-info"></p></section><section><h2>02 領域を選ぶ</h2><div class="row" id="modes"><button data-mode="orbit" class="active">回転</button><button data-mode="face">面</button><button data-mode="brush">ブラシ</button><button data-mode="erase">消しゴム</button><button data-mode="probe">測定</button></div><label>ブラシ半径 <span id="radiusText">6</span> mm<input id="radius" type="range" min="0.1" max="30" step="0.1" value="6"></label><div class="row"><button id="undo">戻す</button><button id="clear">選択解除</button></div><label><input id="wire" type="checkbox"> 表面の三角形を表示</label><details><summary>円筒を角度・長さで選ぶ</summary><label>部品番号（0から）<input id="cylinder-mesh" type="number" value="0" min="0" step="1"></label><label>円筒軸<select id="cylinder-axis"><option value="0">X</option><option value="1" selected>Y</option><option value="2">Z</option><option value="custom" disabled>任意軸（API）</option></select></label><label>軸の基準点 X / Y / Z（mm）</label><div class="direction"><input id="cylinder-x" aria-label="円筒基準X" type="number" value="0" step="any"><input id="cylinder-y" aria-label="円筒基準Y" type="number" value="0" step="any"><input id="cylinder-z" aria-label="円筒基準Z" type="number" value="0" step="any"></div><label>円筒半径（mm）<input id="cylinder-radius" type="number" value="12" min="0.001" step="any"></label><label>半径許容差（mm）<input id="cylinder-tolerance" type="number" value="0.3" min="0" step="any"></label><label>軸方向の開始 / 終了（mm）</label><div class="direction"><input id="cylinder-min" aria-label="軸方向開始" type="number" value="-10" step="any"><input id="cylinder-max" aria-label="軸方向終了" type="number" value="10" step="any"></div><label>開始角度 / 角度幅（°）</label><div class="direction"><input id="cylinder-start" aria-label="開始角度" type="number" value="0" step="any"><input id="cylinder-sweep" aria-label="角度幅" type="number" value="90" min="0.001" max="360" step="any"></div><button id="cylinder-select">数値指定で円筒面を選ぶ</button><button id="cylinder-reapply">保存した指定を再選択</button><p>正の軸方向を右ねじの向きに回ります。角度0はX軸方向（円筒軸がXならY方向）。三角形の中心で判定する近似で、端面は除外します。非表示の裏側も選択対象です。</p></details><div id="area">0 mm²</div><small id="count">選択なし</small><p>ブラシは空間距離による範囲です。見えている同じ面の三角形だけを選択。選択モードでは右ドラッグで回転します。</p></section>
<section><h2>内部を見る</h2><button id="interior-demo">内部面選択サンプル</button><label><input id="clip-enabled" type="checkbox"> 断面表示</label><label>切断方向<select id="clip-axis"><option value="0">X</option><option value="1">Y</option><option value="2" selected>Z</option></select></label><label>切断位置（mm）<input id="clip-position" type="number" value="0" step="any"></label><label><input id="clip-flip" type="checkbox"> 残す側を反転</label><label>形状の透明度<input id="model-opacity" type="range" min="0.1" max="1" step="0.05" value="1"></label><div id="part-visibility"></div><p>部品表示は条件設定画面の操作です。解析対象は全ての部品です。</p><p>切断面には新しい選択面を作りません。露出した元の面を選択できます。半透明でも手前の面が選択されます。奥を選ぶには部品を非表示にしてください。</p></section><section><h2>形状の不備を検査</h2><button id="geometry-inspect">表面を検査</button><button id="geometry-defect-demo">形状不備サンプル</button><div id="geometry-report"></div><p>表示三角形の辺の閉鎖・重複・向きを調べます。自己交差と正確なCAD形状は未検査です。自動修復はせず、元のCAD・メッシュで修正して再読込してください。長さはmmです。</p></section><section><h2>保存・復元</h2><button id="save">プロジェクトを書き出す</button><details><summary>プロジェクトをテキストで受け取る</summary><button id="project-text-show">プロジェクトテキストを表示</button><textarea id="project-text" aria-label="プロジェクトのJSONテキスト" readonly rows="5"></textarea><p>テキストをコピーし、.jsonファイルとして保存して読み込めます。</p></details><label class="file">プロジェクトを開く<input id="restore" type="file" accept=".json"></label><small>表示形状・選択・設定条件を保存</small></section></aside>
<main class="viewport"><canvas id="canvas"></canvas><div class="overlay"><strong id="name">曲面サンプル</strong><div id="status" class="status" role="status">回転して、固定する場所を選んでください。</div></div><div class="hint">ホイール: 拡大縮小 / 右ドラッグ: 選択モードで回転 / 中ドラッグ: 移動<br>黄色: 選択中　青: 拘束　橙: 荷重・指定変位</div></main>
<aside><section><h2>03 解析条件</h2><label>解析分野<select id="physics"><option value="structural">構造</option><option value="thermal">熱</option><option value="fluidDomain">流体領域（メッシュ生成のみ）</option><option value="channelFlow">流体（十分発達した層流流路）</option><option value="acoustic">音響</option></select></label><div data-physics="structural thermal"><label>材料カテゴリ<select id="material"><option>金属</option><option>樹脂</option><option>ガラス</option><option>ゴム</option></select></label><details><summary>材料物性を入力</summary><div id="material-fields"></div><label>グレード<input id="material-grade" maxlength="200"></label><label>物性の出典<input id="material-source" maxlength="1000"></label><label>強度の意味・試験条件<input id="material-notes" maxlength="1000" placeholder="降伏強度、引張強度など"></label><label>温度・速度・方向性のデータ（任意、JSON）<textarea id="material-dependence" rows="7" placeholder='{"elasticTemperatureTable":[{"temperature":20,"youngModulus":1000000000,"poissonRatio":0},{"temperature":80,"youngModulus":500000000,"poissonRatio":0}]}'></textarea></label><p>表のヤング率はPa、温度は°C。速度の範囲は1/s。方向性・速度依存は登録のみで、対応していない構造計算を拒否します。</p><details><summary>圧縮性Neo-Hookeanモデル</summary><label><input id="hyperelastic-enabled" type="checkbox"> 超弾性モデルを使う（構造・CPU）</label><label>せん断弾性率 μ（MPa）<input id="hyperelastic-mu" type="number" value="0.5" min="0.000001" step="any"></label><label>体積弾性率 K（MPa）<input id="hyperelastic-bulk" type="number" value="2" min="0.000001" step="any"></label><label>試験曲線（任意、JSON）<textarea id="hyperelastic-curve" placeholder="[[0.8,-200000],[1,0],[1.2,200000]]"></textarea></label><p>曲線は [伸長比, 公称応力Pa]。登録値の自動フィットは行いません。K/μは2/3〜20。ほぼ非圧縮のゴム、接触、破断、圧力追従荷重は未対応です。</p></details><button id="material-save">物性を登録</button><p id="material-status" role="status"></p></details></div><div data-physics="structural"><label>物性を評価する一様温度（°C）<input id="material-temperature" type="number" value="20" min="-273.15" step="any"></label><p>温度別の弾性定数は線形補間します。熱応力を使う場合は、その部品温度を評価温度に使います。非一様温度での物性補間は未対応です。</p><div class="row"><button id="fixed">選択範囲を固定</button></div><details><summary>方向別拘束・指定変位</summary><label>拘束する軸<select id="constraint-axis"><option value="0">X</option><option value="1">Y</option><option value="2">Z</option></select></label><label><input id="constraint-local" type="checkbox"> 回転した局所座標を使う</label><label>局所座標の回転 X / Y / Z（°）</label><div class="direction"><input id="frame-x" aria-label="局所回転X" type="number" value="0" step="any"><input id="frame-y" aria-label="局所回転Y" type="number" value="0" step="any"><input id="frame-z" aria-label="局所回転Z" type="number" value="0" step="any"></div><label>指定変位（mm）<input id="prescribed-mm" type="number" value="0" step="any"></label><button id="direction-fixed">選択範囲をこの方向だけ固定</button><button id="displacement-add">選択範囲に指定変位</button><p>登録した方向以外は自由です。共有節点で矛盾する指定と、剛体運動が残る拘束を拒否します。</p></details><details><summary>非線形構造の反復設定</summary><label>荷重増分数<input id="nonlinear-steps" type="number" value="10" min="1" max="30"></label><label>増分ごとのNewton反復上限<input id="nonlinear-iterations" type="number" value="30" min="1" max="50"></label><p>超弾性の構造解析では荷重と指定変位を段階的に増やします。2000要素・2000節点まで。未収束なら結果を返しません。</p></details><label>合計荷重（N）<input id="force" type="number" value="100" min="0" step="1"></label><label>全体座標での荷重方向 X / Y / Z</label><div class="direction"><input id="dx" type="number" value="0" aria-label="X方向"><input id="dy" type="number" value="-1" aria-label="Y方向"><input id="dz" type="number" value="0" aria-label="Z方向"></div><div class="row"><button id="load">選択範囲に荷重</button></div><details><summary>圧力・法線荷重・重力</summary><label>圧力（kPa、正は内向き）<input id="pressure-input" type="number" value="1000" step="any"></label><button id="pressure-add">選択範囲に圧力</button><label>法線表面荷重（kPa、正は外向き）<input id="normal-traction" type="number" value="1000" step="any"></label><button id="normal-traction-add">選択範囲に法線表面荷重</button><label><input id="gravity-enabled" type="checkbox"> 重力・一様加速度を使う</label><label>加速度 X / Y / Z（m/s²）</label><div class="direction"><input id="gravity-x" aria-label="加速度X" type="number" value="0" step="any"><input id="gravity-y" aria-label="加速度Y" type="number" value="-9.80665" step="any"><input id="gravity-z" aria-label="加速度Z" type="number" value="0" step="any"></div><p>圧力は各面の法線に沿って作用します。加速度は全部品に作用し、登録済みの密度（kg/m³）が必要です。</p></details><details><summary>熱膨張・熱応力</summary><label><input id="thermal-stress" type="checkbox"> 構造解析に温度変化を適用</label><label>部品温度（°C）<input id="solid-temperature" type="number" value="80" min="-273.15" step="any"></label><label>無応力の基準温度（°C）<input id="reference-temperature" type="number" value="20" min="-273.15" step="any"></label><label>保存した熱解析ケース<select id="thermal-case"></select></label><button id="thermal-case-apply">温度分布を構造解析に使用</button><button id="thermal-case-clear">一様温度に戻す</button><p id="thermal-source-name"></p><p>熱解析をケース保存し、同じ形状に構造の拘束と材料を設定してから選択します。最後の時間ステップの温度を転送します。外部への補外は行いません。</p><p>登録した線膨張係数を使います。温度変化による自由膨張と拘束による応力を計算します。</p></details></div><details data-physics="thermal"><summary>熱の境界条件・時間設定</summary><label>温度（°C）<input id="temperature" type="number" value="20" min="-273.15" step="any"></label><button id="temperature-add">選択範囲に温度を設定</button><label>熱流束（W/m²、流入を正）<input id="heat-flux" type="number" value="1000" step="any"></label><button id="heat-flux-add">選択範囲に熱流束を設定</button><label>合計熱入力（W、流入を正）<input id="heat-power" type="number" value="1" step="any"></label><button id="heat-power-add">選択範囲に合計熱入力を設定</button><label>接触熱伝達率（W/m²K）<input id="contact-h" type="number" value="1000" min="0.001" step="any"></label><button id="contact-add">選択した2部品間に接触熱抵抗</button><p>別々の節点を持つ、同じ位置の平面を両側から選択してください。選択面全体が一致する必要があります。</p><label>放射率（0より大きく1以下）<input id="radiation-emissivity" type="number" value="0.8" min="0.001" max="1" step="any"></label><label>放射の周囲温度（°C）<input id="radiation-ambient" type="number" value="20" min="-273.15" step="any"></label><button id="radiation-add">選択範囲に熱放射</button><label>放射計算の最大反復数<input id="radiation-iterations" type="number" value="30" min="1" max="60"></label><p>大きな等温周囲との灰色体放射（形態係数1）を計算します。部品間の放射は未対応です。</p><label>熱伝達率（W/m²K）<input id="convection-h" type="number" value="100" min="0.001" step="any"></label><label>周囲温度（°C）<input id="ambient-temperature" type="number" value="20" min="-273.15" step="any"></label><button id="convection-add">選択範囲に対流放熱を設定</button><p>熱伝達率は流れ・姿勢などに応じた値を入力します。流体解析からの自動算出は未対応です。</p><label><input id="transient-heat" type="checkbox"> 非定常熱伝導</label><label>時間刻み（秒）<input id="time-step" type="number" value="1" min="0.001" step="any"></label><label>時間ステップ数<input id="time-steps" type="number" value="10" min="1" max="100"></label><label>初期温度（°C）<input id="initial-temperature" type="number" value="20" min="-273.15" step="any"></label><label>体積発熱（W/m³）<input id="volumetric-source" type="number" value="0" step="any"></label></details><details data-physics="channelFlow"><summary>層流流路の設定</summary><label>流路軸<select id="flow-axis"><option value="0">X</option><option value="1" selected>Y</option><option value="2">Z</option></select></label><label>入口から出口への圧力差（Pa）<input id="flow-pressure-drop" type="number" value="0.01" step="any"></label><label>粘度（Pa·s）<input id="flow-viscosity" type="number" value="0.001" min="0.00000001" step="any"></label><label>流体密度（kg/m³）<input id="flow-density" type="number" value="1000" min="0.001" step="any"></label><label>流体の音速（m/s）<input id="flow-sound-speed" type="number" value="1500" min="0.001" step="any"></label><p>内蔵の円筒・角柱を流体領域として使用します。側面は速度0、端面は十分発達した流れです。選択した境界条件は使用できません。STEPの一般流れ・入口の助走区間・曲がり・乱流は未対応です。Re ≤ 1500、Mach ≤ 0.1に制限します。</p></details><details data-physics="acoustic"><summary>音響領域と周波数</summary><p>読み込んだ形状を均一媒質の音響領域として使います。未指定の壁は剛壁です。</p><label>音圧のピーク振幅（Pa）<input id="acoustic-pressure" type="number" value="1" step="any"></label><button id="acoustic-pressure-add">選択範囲に音圧を設定</button><label>吸音境界の抵抗（Pa·s/m）<input id="impedance-r" type="number" value="411.6" min="0.001" step="any"></label><label>リアクタンス（Pa·s/m）<input id="impedance-x" type="number" value="0" step="any"></label><label>周波数特性表（任意、JSON）<textarea id="impedance-table" placeholder="[[500,411.6,0],[5000,411.6,0]]"></textarea></label><button id="impedance-add">選択範囲に吸音境界</button><p>表の行は [Hz, 抵抗, リアクタンス]。抵抗は正、周波数は昇順。線形補間を使い、範囲外は拒否します。未指定面は剛壁です。</p><label>周波数（Hz）<input id="acoustic-frequency" type="number" value="2000" min="1" step="any"></label><label>音速（m/s）<input id="sound-speed" type="number" value="343" min="1" step="any"></label><label>媒質密度（kg/m³）<input id="air-density" type="number" value="1.2" min="0.001" step="any"></label><label>損失係数<input id="acoustic-loss" type="number" value="0.01" min="0" step="any"></label><label>SPLの基準音圧（Pa）<input id="reference-pressure" type="number" value="0.00002" min="0.000000001" step="any"></label><label><input id="acoustic-sweep" type="checkbox"> 周波数スイープ</label><div class="direction"><input id="sweep-start" aria-label="開始周波数" type="number" value="500"><input id="sweep-end" aria-label="終了周波数" type="number" value="5000"><input id="sweep-count" aria-label="周波数点数" type="number" value="12" min="1" max="20"></div><label>受音点 X / Y / Z（mm）</label><div class="direction"><input id="receiver-x" aria-label="受音点X" type="number" value="5" step="any"><input id="receiver-y" aria-label="受音点Y" type="number" value="5" step="any"><input id="receiver-z" aria-label="受音点Z" type="number" value="20" step="any"></div></details></section>
<section><h2>設定した条件</h2><div id="conditions"></div></section><section><h2>計算エンジン</h2><button id="gpu-check">GPU利用環境を確認</button><p id="gpu-environment" role="status"></p><select id="solver"><option value="mfem-wasm">MFEM 4.10 · WASM CPU（構造・別エンジン）</option><option value="webgpu-pcg">Airpocket Tet4 · WebGPU + CPU補正（構造・試験版）</option><option value="wasm-pcg" selected>Airpocket Tet4 · WASM CPU</option><option value="pcg">Airpocket Tet4 · JavaScript</option><option value="pcg-strict">Airpocket Tet4 · JavaScript（厳密収束）</option></select><p>Airpocketは共通の要素モデルの実行方式を選択。MFEMは独立した構造の剛性組立・CGソルバーです。荷重・拘束転送と結果表示は共通です。CalculiX等は未導入。</p><label>メッシュの目標サイズ（mm）<input id="mesh-size" type="number" value="5" min="0.1" step="0.1"></label><details><summary>選択領域のメッシュを細分化</summary><label>局所目標サイズ（mm）<input id="local-mesh-size" type="number" value="2" min="0.1" step="0.1"></label><label>影響半径（mm）<input id="local-mesh-radius" type="number" value="12" min="0.1" step="0.1"></label><button id="local-mesh-add">選択領域の周囲を細分化</button><button id="local-mesh-clear">局所設定を解除</button><p id="local-mesh-count">0 箇所の局所設定</p><p>選択した三角形の中心を起点に、半径内で徐々に細かくします。厳密なCAD境界分割ではありません。局所サイズは全体の15〜100%です。</p></details><label><input id="adaptive-run" type="checkbox"> 結果に応じて局所細分化・再解析</label><label>最大反復回数<input id="adaptive-rounds" type="number" min="1" max="5" value="3"></label><label>適応解析の要素数上限<input id="adaptive-elements" type="number" value="10000" min="1" max="30000" step="1"></label><label>適応解析の時間上限（秒）<input id="adaptive-seconds" type="number" value="60" min="1" max="110" step="1"></label><label>変位の変化許容値（%）<input id="adaptive-tolerance" type="number" value="1" min="0.01" max="99" step="any"></label><label>応力の変化許容値（%）<input id="adaptive-stress-tolerance" type="number" value="5" min="0.01" max="99" step="any"></label><p>少なくとも3回の解析を比較します。特異点は傾向からの推定で、誤差の保証ではありません。時間上限は処理間で確認し、全計算の120秒上限も適用します。</p><div class="row"><button id="mesh-run">体積メッシュを生成</button><button id="solve-run">解析を実行</button><button id="cancel-run" disabled>中止</button></div><p id="mesh-summary"></p><p id="region-report"></p></section><section><h2>結果表示</h2><select id="result-field"><option value="displacement">変位（mm）</option><option value="stress">von Mises応力（MPa）</option><option value="temperature">温度（°C）</option><option value="heatFlux">熱流束（W/m²）</option><option value="pressure">音圧ピーク（Pa）</option><option value="spl">SPL（dB、RMS）</option><option value="phase">位相（rad）</option><option value="speed">流速（m/s）</option><option value="fluidPressure">流体のゲージ圧（Pa）</option></select><label>変形倍率<input id="deform-scale" type="number" value="1" min="0" step="1"></label><label><input id="volume-wire" type="checkbox"> 内部メッシュを表示</label><div class="row"><button id="setup-view">条件設定に戻る</button><button id="result-export" disabled>結果を書き出す</button></div><div id="result-summary" role="status"></div><div id="constraint-reactions"></div><div id="result-legend"></div><pre id="probe-result" style="white-space:pre-wrap;font-size:11px"></pre><div id="sweep-results"></div></section><section><h2>解析ケースの比較</h2><label>ケース名<input id="case-name" maxlength="100" value="Case 1"></label><button id="case-add">現在の計算結果を保存</button><button id="case-export">ケース集を書き出す</button><details><summary>ケース集をテキストで受け取る</summary><button id="case-text-show">ケース集テキストを表示</button><textarea id="case-text" aria-label="ケース集のJSONテキスト" readonly rows="5"></textarea><p>テキストをコピーし、.jsonファイルとして保存して読み込めます。</p></details><label class="file">ケース集を開く<input id="case-import" type="file" accept=".json"></label><p>最大8件。閉じる前に書き出してください。保存結果は再計算せず表示できます。入力だけ復元した場合は再計算してください。</p><div id="case-list"></div></section><div class="notice">線形弾性・圧縮性Neo-Hookean・熱伝導・熱放射・接触熱抵抗・周波数音響・十分発達した層流流路を計算します。外部流体領域はメッシュ生成のみ対応。曲面の部分領域は三角形への投影近似です。一般3D流体・機械的接触・破壊・ほぼ非圧縮のゴムは未対応です。</div></aside></div>`;

const $=id=>document.getElementById(id), status=text=>{const labels={'Material temperature table does not allow extrapolation':'登録した温度表の範囲外です。補外は行いません。','Temperature is outside the registered material validity range':'登録した材料の有効温度範囲外です。','Temperature-dependent elasticity currently requires a uniform temperature':'温度依存の弾性物性には一様温度が必要です。','Rate-dependent structural constitutive models are not supported':'速度依存の構造モデルは未対応です。','Orthotropic structural constitutive models are not supported':'直交異方性の構造モデルは未対応です。','Static structure has zero strain rate, outside the registered test envelope':'静解析のひずみ速度0が登録した試験範囲外です。','Conflicting displacement constraints on a shared node':'共有節点で指定変位が矛盾しています。','Insufficient constraints: rigid motion remains on a disconnected solid (collinear or directional supports)':'拘束不足です。独立した部品の平行移動・回転を止めてください。','Constraint directions are nearly parallel':'拘束方向がほぼ平行です。方向の重複を見直してください。','Calculation cancelled':'計算を中止しました。','Generating volume mesh…':'体積メッシュを生成中…','Transferring boundary regions…':'領域条件を転送中…','Solving linear elasticity…':'構造解析を計算中…','Solving heat conduction…':'熱伝導を計算中…','Solving frequency-domain acoustics…':'音響解析を計算中…'};$('status').textContent=labels[text]||text;};
const renderer=new THREE.WebGLRenderer({canvas:$('canvas'),antialias:true,alpha:true}); renderer.localClippingEnabled=true;renderer.setPixelRatio(Math.min(devicePixelRatio,2));
const scene=new THREE.Scene(), camera=new THREE.PerspectiveCamera(40,1,.01,100000);
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;
scene.add(new THREE.HemisphereLight(0xffffff,0x446079,2.3)); const light=new THREE.DirectionalLight(0xffffff,2.2); light.position.set(50,100,80);scene.add(light);
const group=new THREE.Group();scene.add(group);const markers=new THREE.Group();scene.add(markers);
let meshes=[], conditions=[], mode='orbit', selection=[], history=[], modelName='曲面サンプル', worker=null, pointerDown=false;
let cylindricalRegion=null;
let temperatureSource=null;
let meshSettings={refinements:[]},materialProperties={},sourceModel=null,projectRevision=0,materialDirty=false;
const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();
function geometryData(g,faceIds){if(g.index)g=g.toNonIndexed();g.computeVertexNormals();return {positions:Array.from(g.attributes.position.array),faceIds:faceIds||Array(g.attributes.position.count/3).fill(0)};}
function setModel(data,name){$('fluid-domain-info').textContent='';$('exterior-create').disabled=false;$('clip-enabled').checked=false;$('model-opacity').value=1;$('geometry-report').replaceChildren();cylindricalRegion=null;temperatureSource=null;$('solid-temperature').disabled=false;$('thermal-source-name').textContent='';$('thermal-stress').checked=false;$('gravity-enabled').checked=false;meshSettings={refinements:[]};$('local-mesh-count').textContent='0 箇所の局所設定';projectRevision++;sourceModel=null;clearAnalysis();
 for(const m of meshes){m.geometry.dispose();m.material.dispose();}group.clear();markers.clear();
 meshes=data.map((d,index)=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(d.positions,3));g.computeVertexNormals();g.setAttribute('color',new THREE.Float32BufferAttribute(new Float32Array(d.positions.length),3));const m=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.55,metalness:.18,side:THREE.DoubleSide}));m.userData={index,faceIds:d.faceIds,kind:d.kind||'cad'};group.add(m);return m;});
 selection=meshes.map(()=>new Set());conditions=[];materialProperties={};history=[];modelName=name;$('name').textContent=name;fit();repaint();renderConditions();if($('mat-youngModulus'))renderMaterial();renderPartVisibility();applyViewSettings();
}
function fit(){controls.enableDamping=false;const box=new THREE.Box3().setFromObject(group),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),r=Math.max(size.x,size.y,size.z,1);controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(r*1.4,r*.9,r*1.6));camera.near=r/10000;camera.far=r*100;camera.updateProjectionMatrix();controls.update();controls.enableDamping=true;$('radius').max=Math.max(r/2,1);$('radius').value=Math.min(6,r/10);$('radiusText').textContent=$('radius').value;}
function snapshot(){history.push(selection.map(s=>[...s]));if(history.length>30)history.shift();}
function selectedRegions(){return selection.map((s,mesh)=>({mesh,triangles:[...s]})).filter(r=>r.triangles.length);}
function repaint(){
 let area=0,count=0;
 meshes.forEach((m,mi)=>{const colors=m.geometry.attributes.color;for(let t=0;t<m.userData.faceIds.length;t++){
 let color=new THREE.Color('#91a8b7');for(const c of conditions)if(c.regions.some(r=>r.mesh===mi&&r.triangles.includes(t)))color.set((c.type==='fixed'||c.type==='displacement'&&c.value===0)?'#36b9da':'#f69d53');
 if(selection[mi].has(t)){color.set('#f9d76b');area+=areaOfTriangle(m.geometry.attributes.position.array,t);count++;}for(let v=0;v<3;v++)colors.setXYZ(t*3+v,color.r,color.g,color.b);
 }colors.needsUpdate=true;m.material.wireframe=$('wire').checked;});
 $('area').textContent=area.toLocaleString('ja-JP',{maximumFractionDigits:2})+' mm²';$('count').textContent=count+' 三角形を選択';$('fixed').disabled=$('load').disabled=!count;
 updateMarkers();applyViewSettings();
}
function updateMarkers(){for(const child of [...markers.children]){child.traverse(o=>{o.geometry?.dispose();if(o.material)for(const mat of [].concat(o.material))mat.dispose();});markers.remove(child);}
 const scale=new THREE.Box3().setFromObject(group).getSize(new THREE.Vector3()).length()*.13;
 for(const c of conditions){if(c.type!=='force'||c.regions.every(r=>!meshes[r.mesh].visible))continue;const center=new THREE.Vector3();let n=0;for(const r of c.regions){const p=meshes[r.mesh].geometry.attributes.position;for(const t of r.triangles)for(let v=0;v<3;v++){center.add(new THREE.Vector3().fromBufferAttribute(p,t*3+v));n++;}}if(n){center.divideScalar(n);markers.add(new THREE.ArrowHelper(new THREE.Vector3(...c.direction).normalize(),center,scale,0xffac58));}}
}
function demo(){const g=new THREE.CylinderGeometry(12,12,60,64,24,false).toNonIndexed(),p=g.attributes.position.array;const ids=[];for(let t=0;t<p.length/9;t++){const i=t*9;ids.push(Math.abs(p[i+1]-30)<.001&&Math.abs(p[i+4]-30)<.001&&Math.abs(p[i+7]-30)<.001?1:Math.abs(p[i+1]+30)<.001&&Math.abs(p[i+4]+30)<.001&&Math.abs(p[i+7]+30)<.001?2:0);}setModel([geometryData(g,ids)],language==='en'?'Curved sample · Ø24 × 60 mm':'曲面サンプル · Ø24 × 60 mm');sourceModel={kind:'cylinder'};g.dispose();status('曲面の一部分をブラシで選べます。');}
function hitAt(x,y){const rect=$('canvas').getBoundingClientRect();mouse.set((x-rect.left)/rect.width*2-1,-(y-rect.top)/rect.height*2+1);ray.setFromCamera(mouse,camera);return firstVisibleHit(ray.intersectObjects(meshes.filter(m=>m.visible),false),getViewSettings());}
function paint(event){if(!group.visible)return;const hit=hitAt(event.clientX,event.clientY);if(!hit)return;const m=hit.object,mi=m.userData.index,t=hit.faceIndex,face=m.userData.faceIds[t],p=m.geometry.attributes.position.array;
 let candidates=mode==='face'?m.userData.faceIds.flatMap((f,i)=>f===face?[i]:[]):brushTriangles(p,hit.point,Number($('radius').value));
 const rect=$('canvas').getBoundingClientRect();
 for(const i of candidates){const offset=i*9;const centroid=new THREE.Vector3((p[offset]+p[offset+3]+p[offset+6])/3,(p[offset+1]+p[offset+4]+p[offset+7])/3,(p[offset+2]+p[offset+5]+p[offset+8])/3);if(!viewPointVisible(centroid))continue;if(mode!=='face'){
 if(m.userData.kind==='cad'&&m.userData.faceIds[i]!==face)continue;
 const k=i*9,center=new THREE.Vector3((p[k]+p[k+3]+p[k+6])/3,(p[k+1]+p[k+4]+p[k+7])/3,(p[k+2]+p[k+5]+p[k+8])/3).project(camera);
 if(center.z < -1||center.z>1||Math.abs(center.x)>1||Math.abs(center.y)>1)continue;
 const visible=hitAt(rect.left+(center.x+1)*rect.width/2,rect.top+(1-center.y)*rect.height/2);
 if(!visible||visible.object!==m||visible.faceIndex!==i)continue;
 }if(mode==='erase')selection[mi].delete(i);else selection[mi].add(i);
 }repaint();}
$('canvas').addEventListener('pointerdown',e=>{if(e.button!==0||mode==='orbit')return;if(mode==='probe'){probeAt(e);return;}snapshot();pointerDown=true;$('canvas').setPointerCapture(e.pointerId);paint(e);});
$('canvas').addEventListener('pointermove',e=>{if(pointerDown&&mode!=='face')paint(e);});
for(const type of ['pointerup','pointercancel','lostpointercapture'])$('canvas').addEventListener(type,()=>pointerDown=false);
for(const button of document.querySelectorAll('[data-mode]'))button.onclick=()=>{mode=button.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b===button));controls.mouseButtons.LEFT=mode==='orbit'?THREE.MOUSE.ROTATE:null;controls.mouseButtons.RIGHT=mode==='orbit'?THREE.MOUSE.PAN:THREE.MOUSE.ROTATE;$('canvas').style.cursor=mode==='orbit'?'grab':'crosshair';};
$('radius').oninput=()=>$('radiusText').textContent=$('radius').value;
$('wire').onchange=repaint;$('fit').onclick=fit;$('demo').onclick=demo;
$('clear').onclick=()=>{snapshot();selection.forEach(s=>s.clear());repaint();};$('undo').onclick=()=>{if(history.length){selection=history.pop().map(a=>new Set(a));repaint();}};
function addCondition(type){try{api.addCondition({type,value:type==='force'?Number($('force').value):0,direction:['dx','dy','dz'].map(id=>Number($(id).value))});status('条件を登録しました。まだ解析計算は行っていません。');}catch(error){status(error.message);}}
$('fixed').onclick=()=>addCondition('fixed');$('load').onclick=()=>addCondition('force');
function renderConditions(){const root=$('conditions');root.replaceChildren();if(!conditions.length){root.textContent='条件はまだありません。';return;}conditions.forEach((c,i)=>{const div=document.createElement('div');div.className='condition';const strong=document.createElement('strong');strong.textContent=c.type==='fixed'?`固定 ${i+1}`:c.type==='displacement'?`指定変位 ${i+1} · ${c.value} mm (${c.frame?'局所'+['X','Y','Z'][c.frame.axis]:'全体方向'})`:c.type==='pressure'?`圧力 ${i+1} · ${c.value/1000} kPa（内向きを正）`:c.type==='normalTraction'?`法線荷重 ${i+1} · ${c.value/1000} kPa（外向きを正）`:c.type==='acousticImpedance'?`吸音境界 ${i+1} · ${c.value} + i ${c.reactance??0} Pa·s/m`:c.type==='acousticPressure'?`音圧 ${i+1} · ${c.value} Pa（peak）`:c.type==='temperature'?`温度 ${i+1} · ${c.value} °C`:c.type==='thermalContact'?`接触熱抵抗 ${i+1} · ${c.value} W/m²K`:c.type==='radiation'?`熱放射 ${i+1} · 放射率 ${c.value} / ${c.ambientTemperature} °C`:c.type==='convection'?`対流 ${i+1} · ${c.value} W/m²K / ${c.ambientTemperature} °C`:c.type==='heatPower'?`合計熱入力 ${i+1} · ${c.value} W`:c.type==='heatFlux'?`熱流束 ${i+1} · ${c.value} W/m²`:`荷重 ${i+1} · ${c.value} N`;div.append(strong);const text=document.createElement('small');text.textContent=c.type==='fixed'?'全方向の変位を拘束':c.type==='displacement'?`拘束方向 (${c.direction.map(v=>v.toFixed(4)).join(', ')}) · 全体座標`:c.type==='force'?`方向 (${c.direction.join(', ')}) · 全体座標`:['pressure','normalTraction'].includes(c.type)?'体積メッシュの外向き法線で計算':['acousticPressure','acousticImpedance'].includes(c.type)?'音響の境界条件':'熱の境界条件';div.append(text);if(c.cylindricalRegion){const d=c.cylindricalRegion,info=document.createElement('small');info.textContent='円筒寸法: 半径 '+d.radius+' mm / 軸方向 '+d.axialMin+' → '+d.axialMax+' mm / 角度 '+d.startDegrees+'° + '+d.sweepDegrees+'°';div.append(info);}const row=document.createElement('div');for(const [label,action]of [['領域を選択',()=>{snapshot();api.selectCondition(i);}],['選択範囲で更新',()=>{try{api.replaceConditionRegion(i);status('条件の領域を更新しました。');}catch(e){status(e.message);}}],...(c.cylindricalRegion?[['数値領域を再適用',()=>{try{api.reapplyConditionRegion(i);}catch(e){status(e.message);}}]]:[]),['削除',()=>{api.removeCondition(i);}]]){const b=document.createElement('button');b.textContent=label;b.onclick=action;row.append(b);}div.append(row);root.append(div);});}
function cadImport(buffer){return new Promise((resolve,reject)=>{worker=new Worker(new URL('./cad.worker.js',import.meta.url),{type:'classic'});const timer=setTimeout(()=>{worker?.terminate();worker=null;reject(Error('読み込みが時間制限（90秒）を超えました。'));},90000);const finish=()=>{clearTimeout(timer);worker?.terminate();worker=null;};worker.onmessage=({data})=>{finish();data.error?reject(Error(data.error)):resolve(data.result);};worker.onerror=e=>{finish();reject(Error(e.message));};worker.postMessage({buffer,base:new URL(import.meta.env.BASE_URL,location.href).href},[buffer]);});}
$('model').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>50*1024*1024)throw Error('初期版の上限は50 MBです。');$('model').disabled=true;status('モデルを読み込んでいます…');const buffer=await file.arrayBuffer();const originalBytes=new Uint8Array(buffer.slice(0));if(/\.stl$/i.test(file.name)){const g=new STLLoader().parse(buffer);g.scale(Number($('unit').value),Number($('unit').value),Number($('unit').value));const d=geometryData(g);d.kind='stl';d.faceIds=d.faceIds.map((_,i)=>i);validateProject({version:1,meshes:[d],conditions:[]});setModel([d],file.name);g.dispose();status('STL: 面選択は三角形単位です。ブラシで見えている範囲を選べます。');}else{const result=await cadImport(buffer);const data=result.meshes.map(m=>{const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(m.attributes.position.array,3));g.setIndex(m.index.array);const ids=Array(m.index.array.length/3).fill(-1);m.brep_faces.forEach((f,fi)=>{for(let t=f.first;t<=f.last;t++)ids[t]=fi;});const d=geometryData(g,ids);g.dispose();return d;});validateProject({version:1,meshes:data,conditions:[]});setModel(data,file.name);let binary='';for(let i=0;i<originalBytes.length;i+=16384)binary+=String.fromCharCode(...originalBytes.subarray(i,i+16384));sourceModel={kind:'step',data:btoa(binary)};status('STEP読み込み完了。CAD面またはブラシで領域を指定できます。');}}catch(error){status('読み込み失敗: '+error.message);}finally{$('model').disabled=false;e.target.value='';}};
