async function runAnalysis(solve){if(solve&&($('physics').value==='fluidDomain'||sourceModel?.kind==='fluidDomain')){status('外部流体領域はメッシュ生成のみ対応しています。一般3D流れの計算は未対応です。');return;}if(solve&&materialDirty&&!['acoustic','channelFlow'].includes($('physics').value)){status('物性の変更を登録してから解析してください。');return;}const revision=projectRevision;clearAnalysis();$('mesh-run').disabled=$('solve-run').disabled=true;$('cancel-run').disabled=false;try{const options={size:Number($('mesh-size').value),method:$('solver').value,adaptive:$('adaptive-run').checked,maxRounds:Number($('adaptive-rounds').value),maxAdaptiveElements:Number($('adaptive-elements').value),maxAdaptiveSeconds:Number($('adaptive-seconds').value),tolerance:Number($('adaptive-tolerance').value)/100,stressTolerance:Number($('adaptive-stress-tolerance').value)/100};const output=await(solve?analysis.analyze(options):analysis.generateMesh(options));if(revision!==projectRevision)throw Error('Inputs changed during calculation; run again');lastAnalysis=output;showAnalysis();$('mesh-summary').textContent=output.mesh.summary.nodeCount+' 節点 / '+output.mesh.summary.elementCount+' 四面体 · '+output.mesh.summary.volumeMm3.toFixed(2)+' mm³ / 品質 '+output.mesh.summary.minQuality.toPrecision(3)+' / 品質0.2未満 '+output.mesh.summary.qualityHistogram[0]+' 要素';if(output.boundary)$('region-report').textContent=output.boundary.reports.map(r=>r.type+': 面積誤差 '+(r.relativeAreaError*100).toFixed(1)+'%').join(' / ');if(output.result){const r=output.result;$('result-field').value=r.kind==='channelFlow'?'speed':r.kind==='acoustic'?'pressure':r.kind==='thermal'?'temperature':'displacement';showAnalysis();$('result-summary').textContent=r.kind==='channelFlow'?'最大流速 '+r.maxSpeedMs.toPrecision(5)+' m/s / 平均流速 '+r.meanVelocityMs.toPrecision(5)+' m/s / 入口流量 '+r.inletFlowM3s.toPrecision(5)+' m³/s / 出口流量 '+r.outletFlowM3s.toPrecision(5)+' m³/s / 流量差 '+(r.relativeFlowImbalance*100).toFixed(3)+'% / 圧力差 '+r.pressureDropPa+' Pa / Re '+r.reynolds.toFixed(2)+' / Mach '+r.mach.toExponential(2)+' / 残差 '+r.residual.toExponential(2):r.kind==='acoustic'?'周波数 '+r.frequency.toFixed(1)+' Hz / 最大音圧 '+r.maxPressurePa.toPrecision(5)+' Pa（peak） / 最大SPL '+r.maxSplDb.toFixed(2)+' dB（RMS） / 吸収パワー '+(r.absorbedPowerW??0).toPrecision(5)+' W / 残差 '+r.residual.toExponential(2):r.kind==='thermal'?'温度 '+r.minTemperature.toFixed(3)+' → '+r.maxTemperature.toFixed(3)+' °C / 対流による流入 '+r.convectionHeatW.toPrecision(5)+' W / 放射による流入 '+(r.radiationHeatW??0).toPrecision(5)+' W / 放射反復 '+(r.nonlinearIterations??0)+' / 温度境界の供給 '+r.reactionHeatW.toPrecision(5)+' W / エネルギー収支誤差 '+r.energyBalanceErrorW.toExponential(2)+' W / 残差 '+r.residual.toExponential(2):'最大変位 '+r.maxDisplacementMm.toPrecision(5)+' mm / 最大von Mises '+(r.maxVonMisesPa/1e6).toPrecision(5)+' MPa / 残差 '+r.residual.toExponential(2)+' / 反力 ['+r.reaction.map(v=>v.toFixed(3)).join(', ')+'] N / 合力 ['+r.applied.map(v=>v.toFixed(3)).join(', ')+'] N / 体積荷重 ['+r.bodyLoadN.map(v=>v.toFixed(4)).join(', ')+'] N';appendComputeStatus(r);$('result-export').disabled=false;if(r.contactTransfers?.length){for(const c of r.contactTransfers){const p=document.createElement('p');p.textContent='Contact #'+(c.conditionIndex+1)+' A → B: '+c.fromAToBW.toPrecision(6)+' W';$('result-summary').append(p);}}if(r.constraintRegionReactions?.length){const caption=document.createElement('p');caption.textContent='領域の節点反力（共有節点を含む、全体座標）';$('constraint-reactions').append(caption);for(const group of r.constraintRegionReactions){const p=document.createElement('p');p.textContent='#'+(group.conditionIndex+1)+' ['+group.force.map(v=>v.toFixed(4)).join(', ')+'] N'+(group.directionalReactionN!==null?' / 指定方向 '+group.directionalReactionN.toFixed(4)+' N':'');$('constraint-reactions').append(p);}}if(r.sweep){const table=document.createElement('table');const head=document.createElement('tr');for(const label of ['Hz','Pa peak','dB RMS']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);for(const v of r.sweep.samples){const row=document.createElement('tr');for(const text of [v.frequency.toFixed(1),v.peakPressurePa.toPrecision(4),v.splDb.toFixed(2)]){const td=document.createElement('td');td.textContent=text;row.append(td);}table.append(row);}$('sweep-results').append(table);}} if(output.adaptive){const text=document.createElement('p');text.textContent=(output.adaptive.converged?'変位・応力の変化条件を満たしました。':'収束未確認。')+' '+adaptiveStopText(output.adaptive.stopReason)+' '+output.adaptive.history.map(h=>'#'+h.round+': '+h.elements+' elements / '+h.maxDisplacementMm.toPrecision(4)+' mm').join(' → ');$('result-summary').append(text);const table=document.createElement('table'),head=document.createElement('tr');for(const label of ['#','Elements','mm','MPa','Peak mm','Seconds']){const th=document.createElement('th');th.textContent=label;head.append(th);}table.append(head);for(const h of output.adaptive.history){const tr=document.createElement('tr');for(const value of [h.round,h.elements,h.maxDisplacementMm.toPrecision(4),(h.maxVonMisesPa/1e6).toPrecision(4),h.peakSizeMm.toPrecision(3),h.elapsedSeconds.toFixed(2)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.append(tr);}$('result-summary').append(table);}status(solve?'解析が完了しました。':'体積メッシュを生成しました。');}catch(e){status(e.message);}finally{$('mesh-run').disabled=false;$('solve-run').disabled=$('physics').value==='fluidDomain';$('cancel-run').disabled=true;}}
