const caseStore=createCaseStore();
function viewCase(index){if($('cancel-run').disabled===false)throw Error('先に実行中の計算を中止してください。');const saved=caseStore.list()[index];if(!saved)throw Error('Unknown case');const output=prepareCaseView(saved);api.loadProject(output.input);const o=output.calculation.options;$('mesh-size').value=o.size;$('solver').value=o.method;$('adaptive-run').checked=o.adaptive;$('adaptive-rounds').value=o.maxRounds;restoreAdaptiveOptions(o);lastAnalysis=output;showAnalysis();$('result-export').disabled=false;$('mesh-summary').textContent=output.mesh.summary.nodeCount+' 節点 / '+output.mesh.summary.elementCount+' 四面体';$('result-summary').textContent=saved.name+' · '+caseStore.compare()[index].metrics.map(m=>m.value.toPrecision(5)+' '+m.unit).join(' / ');appendComputeStatus(output.result);status('保存時の入力と結果を表示しています。');return {name:saved.name,kind:output.result.kind};}

function renderCases(){const select=$('thermal-case');select.replaceChildren();for(const [i,c]of caseStore.compare().entries())if(c.kind==='thermal'){const option=document.createElement('option');option.value=i;option.textContent=c.name;select.append(option);}const root=$('case-list');root.replaceChildren();const rows=caseStore.compare();for(const [index,c] of caseStore.list().entries()){const item=document.createElement('article');const title=document.createElement('strong');title.textContent=c.name;item.append(title);const summary=document.createElement('p');summary.textContent=({elastic:'構造',thermal:'熱',acoustic:'音響',channelFlow:'層流流路'}[rows[index].kind])+' · '+rows[index].metrics.map(m=>({maxSpeedMs:'最大流速',outletFlowM3s:'出口流量',maxDisplacementMm:'最大変位',maxVonMisesPa:'最大von Mises',minTemperature:'最低温度',maxTemperature:'最高温度',maxPressurePa:'最大音圧',maxSplDb:'最大SPL'}[m.key])+': '+m.value.toPrecision(5)+' '+m.unit).join(' / ');item.append(summary);for(const [label,action] of [['保存結果を3D表示',()=>viewCase(index)],['入力を複製して復元',()=>{api.loadProject(c.output.input);const o=c.output.calculation.options;$('mesh-size').value=o.size;$('solver').value=o.method;$('adaptive-run').checked=o.adaptive;$('adaptive-rounds').value=o.maxRounds;restoreAdaptiveOptions(o);}],['削除',()=>{caseStore.remove(index);renderCases();}]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{try{action();}catch(e){status(e.message);}};item.append(b);}root.append(item);}}
window.caseApi=Object.freeze({...caseStore,view:viewCase,add(name,output){const result=caseStore.add(name,output);renderCases();return result;},import(value){caseStore.import(value);renderCases();},remove(index){caseStore.remove(index);renderCases();}});
$('case-add').onclick=()=>{try{if(!lastAnalysis?.result)throw Error('Run an analysis first');window.caseApi.add($('case-name').value,lastAnalysis);}catch(e){status(e.message);}};
$('case-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(caseStore.export())],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='simulation-cases.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('case-import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000000)throw Error('Case archive exceeds 100 MB');window.caseApi.import(JSON.parse(await file.text()));}catch(error){status(error.message);}finally{e.target.value='';}};

