function getViewSettings(){return {clipEnabled:$('clip-enabled').checked,axis:Number($('clip-axis').value),position:Number($('clip-position').value),flip:$('clip-flip').checked,opacity:Number($('model-opacity').value),meshCount:meshes.length,hiddenParts:meshes.flatMap((m,i)=>m.visible?[]:[i])};}
function viewPointVisible(point){return visiblePoint(point.toArray(),getViewSettings());}
function applyViewSettings(){const axis=Number($('clip-axis').value),position=Number($('clip-position').value),sign=$('clip-flip').checked?-1:1,normal=new THREE.Vector3();normal.setComponent(axis,sign);if(!Number.isFinite(position))return;const planes=$('clip-enabled').checked?[new THREE.Plane(normal,-sign*position)]:[];for(const m of meshes){m.material.clippingPlanes=planes;m.material.opacity=Number($('model-opacity').value);m.material.transparent=m.material.opacity<1;m.material.depthWrite=m.material.opacity===1;m.material.needsUpdate=true;}analysisLayer.traverse(o=>{if(o.material){o.material.clippingPlanes=planes;o.material.opacity=(o.isLineSegments?.45:($('volume-wire').checked?.3:1))*Number($('model-opacity').value);o.material.transparent=o.material.opacity<1;o.material.depthWrite=o.material.opacity===1;o.material.needsUpdate=true;}});markers.traverse(o=>{if(o.material)for(const mat of [].concat(o.material)){mat.clippingPlanes=planes;mat.needsUpdate=true;}});}
function renderPartVisibility(){const root=$('part-visibility');root.replaceChildren();meshes.forEach((m,i)=>{const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=m.visible;input.disabled=!group.visible;input.onchange=()=>{const hidden=new Set(window.viewApi.get().hiddenParts);if(input.checked)hidden.delete(i);else hidden.add(i);window.viewApi.set({hiddenParts:[...hidden]});};label.append(input,document.createTextNode('部品 '+i+' を表示'));root.append(label);});}
for(const id of ['clip-enabled','clip-axis','clip-position','clip-flip','model-opacity'])$(id).oninput=()=>{try{window.viewApi.set(getViewSettings());}catch(e){status(e.message);}};
window.viewApi=createViewApi({get:getViewSettings,set:s=>{$('clip-enabled').checked=s.clipEnabled;$('clip-axis').value=s.axis;$('clip-position').value=s.position;$('clip-flip').checked=s.flip;$('model-opacity').value=s.opacity;meshes.forEach((m,i)=>m.visible=!s.hiddenParts.includes(i));updateMarkers();applyViewSettings();renderPartVisibility();}});

function interiorExample(){const data=[20,8].map(size=>{const g=new THREE.BoxGeometry(size,size,size).toNonIndexed(),d=geometryData(g);d.faceIds=d.faceIds.map((_,i)=>Math.floor(i/2));g.dispose();return d;});setModel(data,language==='en'?'Interior face selection sample':'内部面選択サンプル');window.viewApi.set({clipEnabled:true,axis:2,position:0,flip:true});status('外側20 mmと内側8 mmの表示サンプル。露出した内側の元の面を選択できます。');}
$('interior-demo').onclick=interiorExample;window.analysisApi.loadInteriorExample=interiorExample;

$('radiation-add').onclick=()=>{try{api.addCondition({type:'radiation',value:Number($('radiation-emissivity').value),ambientTemperature:Number($('radiation-ambient').value)});status('条件を登録しました。');}catch(e){status(e.message);}};
function radiationExample(){thermalExample();api.removeCondition(0);api.selectCondition(0);api.removeCondition(0);api.addCondition({type:'radiation',value:.8,ambientTemperature:20});api.selectCondition(0);api.addCondition({type:'heatPower',value:.8*STEFAN_BOLTZMANN*1e-4*(373.15**4-293.15**4)});api.setStudy({...getProject().study,transient:false,maxRadiationIterations:30});modelName=language==='en'?'Radiation equilibrium reference':'熱放射の平衡参照サンプル';$('name').textContent=modelName;status('放射率0.8、周囲20 °C。合計熱入力との平衡温度の参照値は100 °Cです。');}
$('radiation-demo').onclick=radiationExample;window.analysisApi.loadRadiationExample=radiationExample;

$('contact-add').onclick=()=>{try{api.addCondition({type:'thermalContact',value:Number($('contact-h').value)});status('条件を登録しました。');}catch(e){status(e.message);}};
function contactExample(){thermalExample();const bounds=[[0,0,0,10,10,20],[0,0,20,10,10,20]],data=bounds.map(b=>{const g=new THREE.BoxGeometry(...b.slice(3)).toNonIndexed();g.translate(...b.slice(0,3).map((v,k)=>v+b[k+3]/2));const d=geometryData(g);d.faceIds=d.faceIds.map((_,i)=>Math.floor(i/2));g.dispose();return d;});setModel(data,language==='en'?'Thermal contact reference':'接触熱抵抗の参照サンプル');sourceModel={kind:'boxes',boxes:bounds};api.setStudy({kind:'thermal',transient:false,timeStep:1,steps:10,initialTemperature:20,volumetricSource:0});api.setMaterialProperties({conductivity:2,density:1000,specificHeat:1000});const face=(body,z)=>data[body].positions.reduce((a,_,i)=>{if(i%9===0&&[2,5,8].every(k=>Math.abs(data[body].positions[i+k]-z)<1e-7))a.push(i/9);return a;},[]);api.selectTriangles(0,face(0,0));api.addCondition({type:'temperature',value:100});api.selectTriangles(1,face(1,40));api.addCondition({type:'temperature',value:20});api.selectTriangles(0,face(0,20));api.selectTriangles(1,face(1,20),{replace:false});api.addCondition({type:'thermalContact',value:1000});$('mesh-size').value=4;$('adaptive-run').checked=false;status('接触熱抵抗の参照熱移動量は0.380952 W、界面温度は61.905 / 58.095 °Cです。');}
$('contact-demo').onclick=contactExample;window.analysisApi.loadContactExample=contactExample;

function restoreAdaptiveOptions(o){$('adaptive-elements').value=o.maxAdaptiveElements??10000;$('adaptive-seconds').value=o.maxAdaptiveSeconds??60;$('adaptive-tolerance').value=(o.tolerance??.01)*100;$('adaptive-stress-tolerance').value=(o.stressTolerance??.05)*100;}

function adaptiveStopText(reason){return language==='en'?reason:({'maximum refinement rounds reached':'最大反復数で停止','time limit reached':'時間上限で停止','element limit reached':'要素数上限で停止','mesh refinement stalled':'メッシュの細分化が停滞','suspected stress singularity; peak stress is unresolved':'応力特異点の疑い：最大応力は未収束','displacement, peak stress and stress variation thresholds met':'変位・最大応力・応力変動の条件を達成'}[reason]??reason);}

function flowExample(){demo();sourceModel={kind:'cylinder'};api.setStudy({kind:'channelFlow',flowAxis:1,pressureDropPa:.01,dynamicViscosity:.001,fluidDensity:1000,fluidSoundSpeed:1500});$('adaptive-run').checked=false;$('mesh-size').value=3;modelName=language==='en'?'Fully developed round-pipe flow':'十分発達した円管層流';$('name').textContent=modelName;status('円管の参照最大流速0.006 m/s、流量1.35717e-6 m³/s。メッシュで近似します。');}
$('flow-demo').onclick=flowExample;window.analysisApi.loadFlowExample=flowExample;

async function createExteriorDomain(paddingMm=Number($('fluid-padding').value)){if(!$('cancel-run').disabled)throw Error('先に実行中の計算を中止してください。');const original=api.exportProject(),source=exteriorFluidSource(original,paddingMm);api.loadProject({...original,sourceModel:source,study:{kind:'fluidDomain'},conditions:[],selection:original.meshes.map(()=>[])});const revision=projectRevision;$('mesh-run').disabled=$('solve-run').disabled=true;$('cancel-run').disabled=false;try{const output=await analysis.generateMesh({size:Number($('mesh-size').value),method:$('solver').value});if(projectRevision!==revision)throw Error('Inputs changed during calculation; run again');const mesh=output.mesh,data={positions:mesh.surface.flatMap(f=>f.nodes.flatMap(i=>mesh.nodes.slice(3*i,3*i+3))),faceIds:mesh.surface.map(f=>f.faceTag),kind:'cad'};api.loadProject({...output.input,name:language==='en'?'Exterior fluid domain':'外部流体領域',meshes:[data],selection:[[]],conditions:[]});lastAnalysis={...output,input:api.exportProject()};$('fluid-domain-info').textContent=(language==='en'?'Fluid volume: ':'流体体積: ')+mesh.summary.volumeMm3.toFixed(3)+' mm³';$('mesh-summary').textContent=mesh.summary.nodeCount+' 節点 / '+mesh.summary.elementCount+' 四面体';status('外部流体領域を生成しました。断面表示で部品の空間を確認できます。');return lastAnalysis;}catch(e){if(projectRevision===revision)api.loadProject(original);throw e;}finally{$('mesh-run').disabled=false;$('solve-run').disabled=$('physics').value==='fluidDomain';$('cancel-run').disabled=true;}}
async function exteriorExample(){if(!$('cancel-run').disabled)throw Error('先に実行中の計算を中止してください。');const g=new THREE.BoxGeometry(10,10,10).toNonIndexed();g.translate(5,5,5);const d=geometryData(g);d.faceIds=d.faceIds.map((_,i)=>Math.floor(i/2));setModel([d],language==='en'?'Exterior domain reference':'外部流体領域の参照サンプル');g.dispose();sourceModel={kind:'box',bounds:[0,0,0,10,10,10]};$('mesh-size').value=6;return createExteriorDomain(10);}
$('exterior-create').onclick=()=>createExteriorDomain().catch(e=>status(e.message));$('exterior-demo').onclick=()=>exteriorExample().catch(e=>status(e.message));window.analysisApi.createExteriorDomain=createExteriorDomain;window.analysisApi.loadExteriorExample=exteriorExample;

function updateDisciplineVisibility(){const kind=$('physics').value,hyper=kind==='structural'&&!!materialProperties.hyperelastic;for(const method of ['webgpu-pcg','mfem-wasm'])document.querySelector('#solver option[value="'+method+'"]').disabled=kind!=='structural'||hyper;if((kind!=='structural'||hyper)&&['webgpu-pcg','mfem-wasm'].includes($('solver').value))$('solver').value='wasm-pcg';$('adaptive-run').disabled=kind!=='structural'||hyper;if(kind!=='structural'||hyper)$('adaptive-run').checked=false;for(const el of document.querySelectorAll('[data-physics]')){el.hidden=!el.dataset.physics.split(' ').includes(kind);if(!el.hidden&&kind==='channelFlow'&&el.tagName==='DETAILS')el.open=true;}}
updateDisciplineVisibility();

$('gpu-check').onclick=async()=>{$('gpu-check').disabled=true;try{const info=await checkGpuEnvironment();$('gpu-environment').textContent=info.available?'WebGPUを利用できます: '+info.description+(info.isFallbackAdapter===true?'（ソフトウェア代替）':info.isFallbackAdapter===false?'（実GPU）':''):'WebGPUを利用できません: '+info.reason;}finally{$('gpu-check').disabled=false;}};
window.analysisApi.checkGpuEnvironment=checkGpuEnvironment;

function appendComputeStatus(r){if(r.hyperelastic){const h=r.hyperelastic,p=document.createElement('p');p.textContent='Neo-Hookean / Cauchy / Green-Lagrange / 荷重増分 '+h.loadSteps+' / Newton '+h.newtonIterations+' / 最小J '+h.minJ.toPrecision(6);$('result-summary').append(p);}if(r.materialEvaluation){const m=r.materialEvaluation,p=document.createElement('p');p.textContent='物性評価温度: '+m.temperatureMin.toFixed(3)+' → '+m.temperatureMax.toFixed(3)+' °C'+(m.interpolated?' / 補間ヤング率 '+(m.youngModulus/1e6).toPrecision(6)+' MPa / ポアソン比 '+m.poissonRatio.toPrecision(5):'');$('result-summary').append(p);}if(r.performance){const p=document.createElement('p');p.textContent='計算時間: '+r.performance.solveMs.toFixed(1)+' ms';$('result-summary').append(p);}if(r.native){const p=document.createElement('p');p.textContent='MFEM 4.10 / 倍精度 / 独立剛性組立 / 検証残差 '+r.native.verifiedResidual.toExponential(2);$('result-summary').append(p);}if(!r.gpu)return;const p=document.createElement('p');p.textContent=r.gpu.used?'WebGPU / '+r.gpu.adapter.description+(r.gpu.adapter.isFallbackAdapter===true?'（ソフトウェア代替）':'')+' / GPU '+r.gpu.gpuIterations+' 反復 / CPU補正 '+r.gpu.cpuCorrectionIterations+' / 検証残差 '+r.gpu.verifiedResidual.toExponential(2)+' / GPU処理 '+r.gpu.gpuPhaseMs.toFixed(1)+' ms / CPU補正 '+r.gpu.cpuCorrectionMs.toFixed(1)+' ms':'CPUへ切替: '+r.gpu.fallbackReason;$('result-summary').append(p);}

function rubberExample(){analysisExample();api.selectCondition(1);api.removeCondition(1);api.addCondition({type:'displacement',value:8,direction:[0,0,1]});const triangles=getProject().meshes[0].faceIds.map((_,i)=>i);for(const direction of [[1,0,0],[0,1,0]]){api.selectTriangles(0,triangles);api.addCondition({type:'displacement',value:0,direction});}api.setMaterial('ゴム');api.setMaterialProperties({hyperelastic:{model:'neo-hookean-log',shearModulus:5e5,bulkModulus:2e6,testConditions:'Reference-only constrained uniaxial stretch'}});api.setStudy({...getProject().study,kind:'structural',thermalStress:false,nonlinearLoadSteps:10,maxNewtonIterations:30,gravityEnabled:false});$('solver').value='wasm-pcg';$('mesh-size').value=5;modelName=language==='en'?'Constrained Neo-Hookean stretch':'Neo-Hookeanの拘束した引張';$('name').textContent=modelName;status('横方向の変位を0、上端の変位を8 mmに設定。20%伸長の有限ひずみ参照サンプルです。');}
$('rubber-demo').onclick=rubberExample;

$('project-text-show').onclick=()=>{$('project-text').value=JSON.stringify(api.exportProject());};
$('case-text-show').onclick=()=>{$('case-text').value=JSON.stringify(caseStore.export());};
